changeSet.sql:
-- Restructurings #4..#7 move into group #4, overdue history #13..#34 into group #13; -- stop factors keep their ids, active ones first in the legacy order, emptied groups are removed CREATE TEMP TABLE legacy_member ON COMMIT DROP AS SELECT f.id AS stop_factor_id, g.id AS group_id, g.is_active, g.order_number, min(g.id) OVER family AS target_group_id, row_number() OVER (family ORDER BY g.is_active DESC, g.order_number, f.id) AS position FROM stop_factors.stop_factor f JOIN stop_factors.stop_factor_group g ON g.id = f.group_id WHERE f.metric_id IN (4, 10) WINDOW family AS (PARTITION BY f.metric_id);
UPDATE stop_factors.stop_factor_group g SET is_active = m.is_active, order_number = m.order_number, updated_date = now() FROM (SELECT target_group_id, bool_or(is_active) AS is_active, COALESCE(min(order_number) FILTER (WHERE is_active), min(order_number)) AS order_number FROM legacy_member GROUP BY target_group_id) m WHERE g.id = m.target_group_id;
-- Negative order first: uq_stop_factor_order is checked per row UPDATE stop_factors.stop_factor f SET order_number = -f.id FROM legacy_member m WHERE f.id = m.stop_factor_id;
UPDATE stop_factors.stop_factor f SET group_id = m.target_group_id, order_number = m.position FROM legacy_member m WHERE f.id = m.stop_factor_id;
DELETE FROM stop_factors.stop_factor_group g USING legacy_member m WHERE g.id = m.group_id AND g.id <> m.target_group_id;

rollback.sql:
INSERT INTO stop_factors.stop_factor_group (id, created_date, description, is_active, order_number,
                                            version_number, valid_from, created_by)
SELECT f.id, f.created_date, g.description, f.is_active, g.order_number,
       1, COALESCE(f.created_date, g.valid_from), 'migration'
FROM stop_factors.stop_factor f
JOIN stop_factors.stop_factor_group g ON g.id = f.group_id
WHERE f.group_id IN (4, 13) AND f.id <> f.group_id;

UPDATE stop_factors.stop_factor SET order_number = -id WHERE group_id IN (4, 13);
UPDATE stop_factors.stop_factor SET group_id = id, order_number = 1 WHERE group_id IN (4, 13);

UPDATE stop_factors.stop_factor_group g
SET is_active = f.is_active
FROM stop_factors.stop_factor f
WHERE f.id = g.id AND g.id IN (4, 13);

changeSet.sql:
CREATE TEMP TABLE new_version ON COMMIT DROP AS SELECT g.id AS previous_id, nextval('public.stop_factor_group_id_generator') AS id, l.rejected_above FROM stop_factors.stop_factor_group g JOIN (VALUES (11, '3'), (12, '7')) AS l (group_id, rejected_above) ON l.group_id = COALESCE(g.root_id, g.id) WHERE g.valid_to IS NULL;
CREATE TEMP TABLE new_factor ON COMMIT DROP AS SELECT f.id AS previous_id, nextval('public.stop_factor_id_generator') AS id, v.id AS group_id, v.rejected_above FROM stop_factors.stop_factor f JOIN new_version v ON v.previous_id = f.group_id;
UPDATE stop_factors.stop_factor_group SET valid_to = now() WHERE id IN (SELECT previous_id FROM new_version);
INSERT INTO stop_factors.stop_factor_group (id, created_date, description, is_active, order_number, root_id, version_number, valid_from, change_reason, created_by) SELECT v.id, now(), g.description, g.is_active, g.order_number, COALESCE(g.root_id, g.id), g.version_number + 1, now(), 'Новые общие ограничения 2026', 'migration' FROM new_version v JOIN stop_factors.stop_factor_group g ON g.id = v.previous_id;
INSERT INTO stop_factors.stop_factor (id, created_date, group_id, metric_id, name, order_number, is_active, params, segment) SELECT n.id, now(), n.group_id, f.metric_id, f.name, f.order_number, f.is_active, f.params, f.segment FROM new_factor n JOIN stop_factors.stop_factor f ON f.id = n.previous_id;
INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, value, value_type, result, operator, value_to) SELECT nextval('public.stop_factor_condition_id_generator'), now(), n.id, CASE WHEN c.result = 'REJECTED' THEN n.rejected_above ELSE c.value END, c.value_type, c.result, c.operator, c.value_to FROM new_factor n JOIN stop_factors.stop_factor_condition c ON c.stop_factor_id = n.previous_id;
INSERT INTO stop_factors.stop_factor_product (stop_factor_id, product_id) SELECT n.id, p.product_id FROM new_factor n JOIN stop_factors.stop_factor_product p ON p.stop_factor_id = n.previous_id;

rollback.sql:
CREATE TEMP TABLE removed_version ON COMMIT DROP AS
SELECT id, root_id, valid_from
FROM stop_factors.stop_factor_group
WHERE change_reason = 'Новые общие ограничения 2026' AND created_by = 'migration' AND valid_to IS NULL;

DELETE FROM stop_factors.stop_factor_condition
WHERE stop_factor_id IN (SELECT f.id FROM stop_factors.stop_factor f JOIN removed_version r ON r.id = f.group_id);

DELETE FROM stop_factors.stop_factor_product
WHERE stop_factor_id IN (SELECT f.id FROM stop_factors.stop_factor f JOIN removed_version r ON r.id = f.group_id);

DELETE FROM stop_factors.stop_factor WHERE group_id IN (SELECT id FROM removed_version);
DELETE FROM stop_factors.stop_factor_group WHERE id IN (SELECT id FROM removed_version);

UPDATE stop_factors.stop_factor_group g
SET valid_to = NULL
FROM removed_version r
WHERE COALESCE(g.root_id, g.id) = r.root_id AND g.valid_to = r.valid_from;

changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM overdue_rule_product WHERE product_id IS NULL) THEN
        RAISE EXCEPTION 'Products of the requirements are not in public.product: %',
            (SELECT string_agg(name, ', ') FROM overdue_rule_product WHERE product_id IS NULL);
    END IF;
END $$;

WITH closed AS ( UPDATE stop_factors.stop_factor_group SET valid_to = now() WHERE COALESCE(root_id, id) = 13 AND valid_to IS NULL RETURNING order_number, version_number ) INSERT INTO stop_factors.stop_factor_group (id, created_date, description, is_active, order_number, root_id, version_number, valid_from, change_reason, created_by) SELECT nextval('public.stop_factor_group_id_generator'), now(), 'Розница и ИФЦ, МСБ', true, order_number, 13, version_number + 1, now(), 'Правила по просрочкам 2026', 'migration' FROM closed;
INSERT INTO stop_factors.stop_factor (id, created_date, group_id, metric_id, name, order_number, is_active, params, segment) SELECT r.id, now(), g.id, 10, r.name, r.order_number, true, jsonb_strip_nulls(jsonb_build_object('periodFromMonth', r.period_from, 'periodToMonth', r.period_to, 'minOverdueDays', r.min_days, 'maxOverdueDays', r.max_days)), r.segment FROM overdue_rule r JOIN stop_factors.stop_factor_group g ON g.root_id = 13 AND g.valid_to IS NULL ORDER BY r.order_number;
INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, value, value_type, result, operator, value_to) SELECT nextval('public.stop_factor_condition_id_generator'), now(), r.id, c.value, 'INTEGER', c.result, c.operator, c.value_to FROM overdue_rule r CROSS JOIN LATERAL (VALUES ('REJECTED', r.rejected_above::text, 'GT', NULL), ('UNDERWRITER', r.underwriter_above::text, 'RANGE', r.rejected_above::text)) AS c (result, value, operator, value_to) WHERE c.value IS NOT NULL ORDER BY r.order_number, c.result;
INSERT INTO stop_factors.stop_factor_product (stop_factor_id, product_id) SELECT r.id, p.product_id FROM overdue_rule r JOIN overdue_rule_product p ON p.segment = r.segment;

